/* Loud Rattlesnake 53 by JayRamoliya — https://uiverse.io/JayRamoliya/loud-rattlesnake-53 */
.input-style {
  padding: 10px;
  border: 2px solid #ccc;
  border-radius: 5px;
  font-size: 16px;
  color: #555;
  outline: none;
}

.input-style:focus {
  border-color: #007bff;
  box-shadow: 0 0 0 0.2rem rgba(0, 123, 255, 0.25);
}
